def lit(d):
 if 'lighting' in d:return d['lighting']=='With LED'
 s=d.get('productionNotes','').lower();return 'led' in s and not any(t in s for t in ['no led','without led'])
def kind(d):return 'Charcoal & engraved' if d['category']=='Engraved Mandala' else d['category']
def pic(d):return d['images'][0]['src']
def card(d):
 return f'''<article class="current-card" data-current-design="{d['id']}"><a class="current-card-image" href="{d['productUrl']}"><img src="{pic(d)}" alt="{E(d['name'])}" width="{d['images'][0]['width']}" height="{d['images'][0]['height']}" loading="lazy"><span>{'LED' if lit(d) else 'No LED'}</span></a><div class="current-card-info"><p>{E(kind(d))} · {d['id']}</p><h3><a href="{d['productUrl']}">{E(d['name'])}</a></h3><div class="card-bottom"><strong>₹{d['pricePerSqIn']} <small>/ sq in</small></strong><a href="{d['productUrl']}" aria-label="Customise {E(d['name'])}">Customise ↗</a></div></div></article>'''
def cards(items):return '<div class="current-grid">'+''.join(card(d) for d in items)+'</div>'
