# Apply shared chrome and the theme to every existing product and information page.
for target in R.rglob('*.html'):
 text=target.read_text()
 if '<body' not in text:continue
 text=re.sub(r'<body([^>]*)>',lambda m:'<body'+(re.sub(r'class="([^"]*)"',lambda c:'class="'+c[1]+(' nis-luxe' if 'nis-luxe' not in c[1] else '')+'"',m[1]) if 'class=' in m[1] else m[1]+' class="nis-luxe"')+'>',text,count=1)
 text=re.sub(r'<(?:div|a) class="(?:studio-topbar|offer-topline)"[^>]*>.*?</(?:div|a)>\s*(?=<header)', '', text, count=1, flags=re.S)
 text=re.sub(r'<header\b[^>]*>.*?</header>',header,text,count=1,flags=re.S)
 text=re.sub(r'<footer\b[^>]*>.*?</footer>',footer,text,count=1,flags=re.S)
 text=re.sub(r'<link[^>]*href="/(?:storefront-theme|atelier-theme).css[^>]*>','',text)
 text=re.sub(r'<meta name="theme-color"[^>]*>','',text)
 text=text.replace('</head>','<meta name="theme-color" content="#1e73be"></head>')
 text=text.replace('</head>','<link rel="stylesheet" href="/storefront-theme.css?v='+V+'"></head>')
 text=re.sub(r'/shop-theme.js\?v=[^"\s]+','/shop-theme.js?v='+V,text)
 if target==R/'index.html':
  text=text.replace('/storefront-theme.css?v='+V,'/storefront-theme.css?v='+V+'-social').replace('/home.js?v='+V,'/home.js?v='+V+'-social')
 target.write_text(text)
